        task_id = rec.get("task_id")
        ledger, journal = ledger_view(self.ledger_path, task_id), journal_view(self.journal_path, task_id)
        server = self._server_turn(rec.get("turn_id"))
        state, reason, corroboration = corroborate(rec, ledger, journal, server, self._task_exists)
        return {**rec, "state": state, "reason": reason, "recorded_state": rec.get("state"), "corroboration": corroboration,
                "ledger": ledger, "journal": journal, "server_turn": server}

    def list(self):
